actionCenter.showDialog:
({dataCenter, actionCenter, globalUtils}, eventParams) => {
  let Params = eventParams.params
  console.log("showDialog", Params)
  if(Array.isArray(Params)){
    Params = Params[0]
  }
  let visibleProperty = Params.activateText
  const visibleName = Params.name
  let val = Params?.val
  if(visibleProperty === "addDialogVisible" && visibleName === "新增" ){
    dataCenter.dbManagementDialogTitle = "新增弹窗"
    if(dataCenter.currentSelectTabKey === "component_param"){
      visibleProperty = "partsDialogVisible"
      val = "component"
    }
  }
  dataCenter[visibleProperty] = !dataCenter[visibleProperty]
  if(Params?.onlyOpenDialog) return
  const params = {
    type: visibleProperty,
    name: visibleName,
    val
  }
  actionCenter.handButton(params)
}

