actionCenter.useAxios:
({dataCenter, actionCenter, globalUtils}, eventParams) => {
  const { axios, openConfirmBox} = globalUtils
  const cookies = actionCenter.useCookie()
  // 创建axios实例
  const service = axios.create({
    baseURL: actionCenter.constant("baseHost"), // api的base_url
    timeout: 60000,// 请求超时时间
    withCredentials: true
  });

  // 请求拦截器
  service.interceptors.request.use(
    config => {
      // 可以在这里添加请求头等信息
      const token = dataCenter.tempToken || cookies.getCookie("token")
      if(token){
        config.headers['authorization'] = "Bearer " + token;
      }
      console.log("请求拦截器", config);
      dataCenter.globalMessage = "计算中..."
      dataCenter.globalIsLoading = true
      return config;
    },
    error => {
      console.log("请求拦截器报错", error);
      Promise.reject(error);
    }
  );

  // 响应拦截器
  service.interceptors.response.use(
    response => {
      if (response.config?.responseType === 'blob') {
        dataCenter.globalMessage = "就绪"
        dataCenter.globalIsLoading = false
        return response;
      }
      // 对响应数据做处理，例如只返回data部分
      const res = response.data;
      console.log("响应拦截器", res, response)
      // 如果返回的状态码为200，说明成功，可以直接返回数据
      if (res.code === 200) {
        dataCenter.globalMessage = "就绪"
        dataCenter.globalIsLoading = false
        return res;
      } else {
        // 其他状态码都当作错误处理
        // 可以在这里对不同的错误码进行不同处理
        dataCenter.globalMessage = "就绪"
        dataCenter.globalIsLoading = false
        openConfirmBox({
          title: '错误',
          sureText: '确定',
          message: res.msg ?? "程序繁忙，请稍后重试。"
        })
        return Promise.reject({
          message: res.msg || 'Error',
          status: res.code
        });
      }
    },
    error => {
      // 对响应错误做处理
      console.log("响应拦截器错误", error);
      if(error.response.data.code === 401 && error.response.data.message === "Missing or invalid token"){
        const pubFun = actionCenter.usePublicMethod()
        pubFun.ReLogin()
      }
      dataCenter.globalMessage = "就绪"
      dataCenter.globalIsLoading = false
      if(error.message){
        openConfirmBox({
            title: '错误',
            sureText: '确定',
            message: error.message ?? "程序繁忙，请稍后重试。"
        })
      }
      return Promise.reject(error);
    },
  )
  return service
}

