actionCenter.apis:
({dataCenter, actionCenter, globalUtils}, eventParams) => {
  const service = actionCenter.useAxios()
  // post 请求
  const postFun = async (urlPath, data, config = {}) =>{
    try {
      const response = await service.post(urlPath, data, config);
      console.log("postFun", response);
      if (response.config?.responseType === 'blob') {
        return response;
      }
      return response.data ?? response
    } catch (error) {
      console.error('post提交失败:', error);
      if (error.response) {
          // 处理服务器返回的错误
          console.error('服务器返回错误:', error.response.status, error.response.data);
          return { status: error.response.status, data: error.response.data };
      } else {
          // 处理网络错误等其他错误
          console.error('网络或其他错误:', error.message);
          return { error: error.message };
      }
      return error
    }
  }
  // get 请求
  const getFun = async (urlPath, params)=>{
    try {
      const response = await service.get(urlPath, {params});
