actionCenter.goLoginOrRegister:
async ({dataCenter, actionCenter, globalUtils}, eventParams) => {
  const { isEmpty, openConfirmBox } = globalUtils
  const { InLoginOrRegister, loginOrRegisterForm } = dataCenter
  if(isEmpty(loginOrRegisterForm.username) || isEmpty(loginOrRegisterForm.password)) return
  const apis = actionCenter.apis()
  if(InLoginOrRegister === "登录"){
    const cookies = actionCenter.useCookie()
    const res = await apis.login(loginOrRegisterForm)
    if(res.code !== 200 && res.msg !== "操作成功") return
    cookies.setCookie("token", res.token, 7)
    dataCenter.tempToken = res.token
    const resUsers = await apis.getUserInfo()
    console.log("查询用户详细", resUsers)
    if(resUsers.code == 200){
      dataCenter.userInfo = {
        name: resUsers.data.nickName,
        remark: resUsers.data.remark ?? "normal_account"
      }
    }
    dataCenter.isLogin = !dataCenter.isLogin
    localStorage.setItem('username', loginOrRegisterForm.username);
    const params = {
        type: "currentMenuBar",
        val: dataCenter.userInfo.remark == "normal_account" ? "车辆定义" : "数据管理" 
    }
    actionCenter.useRequestControlCenter(params)
  }
  if(InLoginOrRegister === "注册"){
    const res = await apis.register(loginOrRegisterForm)
    if(res.code === 200 && res.msg === "操作成功"){
      openConfirmBox({
          title: '提示',
          sureText: '确定',
          message: "账号注册成功"
      })
    }
  }
}

