actionCenter.useCookie:
({dataCenter, actionCenter, globalUtils}, eventParams) => {
  /**
   * 设置cookie
   * @param {*} key 名称
   * @param {*} val 值
   * @param {*} time 失效时间
   */
   const setCookie = (key, val, expiresDays) => {
      let date = new Date();
      //将时间转换为cookie设置时间的格式
      date.setTime(date.getTime() + expiresDays * 24 * 3600 * 1000);
      document.cookie = key + "=" + val + ";expires=" + date.toDateString();
   }
  /**
   * 获取cookie
   * @param {*} key 名称
   */
   const getCookie = (key) => {
    let getCookie = document.cookie.replace(/[ ]/g, "");
    let arrCookie = getCookie.split(";")
    let tips;
    for (let i = 0; i < arrCookie.length; i++) {
      let arr = arrCookie[i].split("=");
      if (key == arr[0]) {
        tips = arr[1];
        break;
      }
    }
    return tips;
  }
  // 删除
  const deleteCookie = (key)=>{
    setCookie(key,'',-1)
  }
  return {
    setCookie,
    getCookie,
    deleteCookie
  }
}

actionCenter.usePublicMethod:
({dataCenter, actionCenter, globalUtils}, eventParams) => {
  const { isEmpty, openConfirmBox } = globalUtils
  // 重新登录
  const ReLogin = ()=> {
     const cookies = actionCenter.useCookie()
     cookies.deleteCookie("token")
     localStorage.removeItem('username')
     dataCenter.userInfo.name = "未登录"
     dataCenter.isLogin = false
  }
  // 将表头数据转为form表单结构
  function transformAtoB(a, labval = { lab: "title", val: "value", name: "key"}, excludeKeys = ["operate"]) {
      if(isEmpty(a)) return a
      return a
          .filter(item => !excludeKeys.includes(item.key)) // 过滤掉 excludeKeys 中的项
          .map(item => {
              // 基础映射
              const transformedItem = {
                  name: item[labval.name],       // key -> name
                  label: item[labval.lab],    // title -> label
                  type: item.type || "input", // 如果没有 type，默认是 input
                  value: item[labval.val] !== undefined ? item[labval.val] : getDefaultValue(item.type), // 根据 type 设置默认值
              };
              // 保留其他属性（如 disabled、slot、width 等）
              for (const key in item) {
                  if (!["key", "title", "type", "value"].includes(key)) {
                      transformedItem[key] = item[key];
                  }
              }
              return transformedItem;
          });
  }
  // 根据 type 设置默认值
  function getDefaultValue(type) {
      switch (type) {
          case "checkbox":
              return false; // checkbox 默认值为 false
          case "select":
              return null; // select 默认值为 null
          default:
              return ""; // 其他类型默认值为空字符串
      }
  }
  /**
   * 将结构提取为 { name: value } 的形式
   * @param {Array} data - 原始数据结构
   * @returns {Object} - 提取后的 { name: value } 对象
   */
  function extractNameValue(data) {
      return data.reduce((result, item) => {
          if(item.type === "table"){
            result[item.name] = JSON.stringify(item.dataSource)
          }else if(item.type === "select"){
              const idVal =  item.options.find(itemVal => itemVal.label === item.value )
              if(idVal){
                result[item.name] = idVal.value
              }else{
                result[item.name] = item.value
              }
          }else{
             result[item.name] = item.value; // 将 name 作为键，value 作为值
          }
          return result;
      }, {});
  }
  // 刷新数据管理表格内容
  function RefreshCurrTabInfo() {
    const params = {
        type: "RefreshCurrTabInfo",
        val: "刷新"
    }
    actionCenter.handButton(params)
  }
  /**
   * 根据指定属性对数组进行排序
   * @param {Array} data - 需要排序的数组
   * @param {string} key - 排序依据的属性名
   * @param {string} order - 排序顺序，'asc' 表示升序，'desc' 表示降序，默认为 'asc'
   * @returns {Array} - 排序后的数组
   */
  function sortByKey(data, key, order = 'asc') {
      if (!Array.isArray(data)) {
          throw new Error('Data must be an array');
      }
      return data.sort((a, b) => {
          // 如果属性不存在，将其排在最后
          if (a[key] === undefined || b[key] === undefined) {
              return a[key] === undefined ? 1 : -1;
          }
          if (a[key] < b[key]) {
              return order === 'asc' ? -1 : 1;
          }
          if (a[key] > b[key]) {
              return order === 'asc' ? 1 : -1;
          }
          return 0; // 如果相等，保持原有顺序
      });
  }
  // 提取数组指定字段值
  function getArrayPropertyVal(dataArray, property, needRetainProperty = []) {
    if (!Array.isArray(dataArray)) {
        console.warn("输入的不是数组，直接返回空数组");
        return [];
    }
    const propertys = [];
    let left = 0; // 左指针
    let right = dataArray.length - 1; // 右指针
    while (left <= right) {
        propertys.push(BuildDropOption(dataArray[left], property, left, needRetainProperty));
        if (left !== right) {
            propertys.push(BuildDropOption(dataArray[right], property, right, needRetainProperty));
        }
        left++;
        right--;
    }
    return propertys;
  }
  // 构建下拉框结构
  function BuildDropOption(data, property, index, needRetainProperty) {
    let otherProperty = {}
    if(!isEmpty(needRetainProperty)){
      needRetainProperty.forEach((value) => {
          if(!isEmpty(data[value])){
            otherProperty[value] = data[value]
          }
      });
    }
    return {
      index,
      lable: data[property],
      value: data[property],
      ...otherProperty
    }
  }
  // 给数组对象快速添加属性
  function addFieldsToItem(data, Fields) {
    if(isEmpty(data)) return []
    return data?.map((item, index) => {
      return {
         name: index === 0 ?  "ErTabs1" : "name" + index,
         ...Fields,
         ...item
      }
    })
  }
  /** 转换为树形结构
  * data：原始数据。
  * parentId：父节点的 ID，用于生成当前节点的 ID。
  * level：当前层级，用于控制递归深度。
  */
  function transformData(data, parentId = 0, level = 1) {
      if(isEmpty(data)) return []
      let idCounter = parentId + 1; // ID 计数器
      return data.map((item, index) => {
          const currentId = idCounter++; // 当前节点的 ID
          const newItem = {
              id: currentId,
               ...item
          };
          // 如果有 params，递归处理
          if (item.params && item.params.length > 0) {
              newItem.children = transformData(
                  item.params.map(param => ({
                      ...param
                  })),
                  currentId,
                  level + 1
              );
          }
          return newItem;
      });
  }
  /**
   * 将数组转换为指定格式
   * @param {Array} data - 原始数据数组
   * @param {string} labelKey - 指定作为 label 的字段
   * @param {string} valueKey - 指定作为 value 的字段
   * @returns {Array} - 转换后的数组，格式为 [{ label: xxx, value: xxx }]
   */
  function transformOption(data, labelKey, valueKey) {
      return data.map(item => ({
          label: item[labelKey],
          value: item[valueKey]
      }));
  }
  /**
   * 在数组中找到指定 key 的对象，并添加新属性
   * @param {Array} data - 原始数据数组
   * @param {string} targetKey - 要查找的 key
   * @param {string} newProp - 要添加的新属性名
   * @param {any} newValue - 要添加的新属性值
   * @returns {Array} - 修改后的数组
   */
  function addPropertyToObject(data, targetKey, newProp, newValue) {
      return data.map(item => {
          if (item.key === targetKey) {
              // 找到目标对象，添加新属性
              if(newProp === "options" && item.type !== "select"){
                return { ...item, [newProp]: newValue, type: "select" };
              }
              return { ...item, [newProp]: newValue };
          }
          // 其他对象保持不变
          return item;
      });
  }

 // 指定格式命名
  function formattedNaming(name, str) {
    if(isEmpty(name)) return
    const lastIndex = name.lastIndexOf('-[');
    if (lastIndex !== -1) {
        const newStr = name.slice(0, lastIndex) + str + name.slice(lastIndex);
        return newStr;
    }
    return name + str;
  }

  // 清除数据
  function clearAllData(params) {
    dataCenter.curVehicleTaskObj = []
    dataCenter.VehicleTaskList = []
  }

  //表单校验
  function isEmptyFormValid(Form) {
    return Object.values(Form).some(value => isEmpty(value));
  }

  /**
   * 根据指定的属性值和属性名筛选对象数组
   * @param {Array} values - 需要匹配的值数组
   * @param {Array} objects - 需要筛选的对象数组
   * @param {string} key - 需要匹配的属性名
   * @returns {Array} - 返回匹配的对象数组
   */
  function filterObjectsByValues(values, objects, key) {
      // 使用 filter 方法筛选出指定属性值匹配的对象
      console.log("filterObjectsByValues", values, objects, key)
      return objects.filter(obj => {
          // 检查当前对象的指定属性值是否在 values 数组中
          return values.includes(obj[key]);
      });
  }

  // 初始化表单的值
  function formInitialValue(formItem, itemVal){
    console.log("formInitialValue表头",formItem, "值", itemVal)
    const newformItem = formItem?.map(item =>{
      // 补充table
      if(item.type === "table" && !isEmpty(item.config)){
        const config = JSON.parse(item.config)
        item['columns'] = config.columns
        item['dataSource'] = JSON.parse(itemVal[item['name']]) || []
      }
      // 补充value
      if(itemVal[item['name']]){
        item['value'] = itemVal[item['name']]
      }
      return item
    })
    return newformItem
  }

  // 表格数组转换为值
  function transformToValueArray(columns, dataSource, formatter) {
    const keys = columns.map(col => col.key);
    return dataSource.map(item => 
      keys.map(key => formatter(item[key], key))
    );
  }

  // 清除数据对比
  function clearAllPlotData(){
    const initData = actionCenter.constant("initPlotData")
    dataCenter.plotWinList = initData
    dataCenter.curPlotWin = {}
    dataCenter.tableWinList = []
    dataCenter.curTableWin = []
  }
  return {
    ReLogin,
    transformAtoB,
    extractNameValue,
    RefreshCurrTabInfo,
    sortByKey,
    addFieldsToItem,
    getArrayPropertyVal,
    transformData,
    transformOption,
    addPropertyToObject,
    clearAllData,
    formattedNaming,
    isEmptyFormValid,
    filterObjectsByValues,
    formInitialValue,
    transformToValueArray,
    clearAllPlotData
  }
}

