async ({dataCenter, actionCenter, globalUtils}, eventParams) => {
    const params = eventParams.params[0]
    console.log("useRequestControlCenter", eventParams, params)
    const apis = actionCenter.apis()
    switch (params.type) {
      case 'currentMenuBar':
        await currentMenuBar(apis, dataCenter, actionCenter, params.val)
        break;
      case 'RefreshCurrTabInfo':
      case 'currentSelectTabKey':
        await currentDbTab(apis, dataCenter, actionCenter)
        break;
      case 'ModelImportDialogVisible':
        await modelImport(apis, dataCenter, actionCenter, globalUtils)
        break;
      case 'ModifiedEntry':
        await ModifiedEntry(apis, dataCenter, actionCenter, globalUtils)
        break;
      case 'addDialogVisible':
