// 报告生成
async function generateReport(apis, dataCenter, actionCenter, globalUtils, params){
  const { uploadPlotlyToBlob, isEmpty } = globalUtils
  console.log("generateReport", params, "绘图", dataCenter.plotWinList, "表格数据", dataCenter.tableWinList)
  let taskList = []
  let plotData = []
  let tableData = []
  // 遍历 绘图数据
  if(dataCenter.plotWinList.length > 0){
    for (let i = 0; i < dataCenter.plotWinList.length; i++) {
        const item = dataCenter.plotWinList[i];
        const domRef = document.getElementById(item.propValue.domId);
        if (isEmpty(item.propValue.dataSource)) continue;
          let svgFile = await uploadPlotlyToBlob({ domRef, fileName: item.name, format: "png"});
        if (!svgFile) continue;
        plotData.push(svgFile);
        taskList = [...taskList, ...item.DataComparisonValue]
    }
  }
  // 遍历 表格数据
  if(dataCenter.tableWinList.length > 0){
    taskList = [...taskList, ...dataCenter.DataOptionsValue?.map(item => item.label)]
    dataCenter.tableWinList.forEach(item => {
      tableData.push({
          title: item.name,
          columns: item.propValue.columns,
          dataSource: item.propValue.dataSource
      })
    })
  }
  taskList = [...new Set(taskList)]
  console.log("generateReport---数组准备绘图", plotData, "任务名称", taskList ,"表格数据", tableData)
  if(isEmpty(plotData) && isEmpty(taskList) && isEmpty(tableData)) return
  const formData = new FormData();
  formData.append('taskName', JSON.stringify(taskList));
  if(isEmpty(plotData)){
    formData.append('images', plotData);
  }else {
    plotData?.forEach((file) => {
       formData.append("images", file, file.name);
    });
  }
  formData.append('tables', JSON.stringify(tableData));
  let res = await apis.generateReport(formData)
  console.log("generateReport---请求发送结果res", res)
  if(res?.status !== 200) return
  try {
    // 提取文件名
    const disposition = res.headers['content-disposition'];
    let filename = 'report.pptx';
    if (disposition) {
      const utf8Match = disposition.match(/filename\*=UTF-8''(.+?)(;|$)/);
      filename = utf8Match ? decodeURIComponent(utf8Match[1]) : (disposition.match(/filename="?(.+?)"?(;|$)/)?.[1] || filename);
      console.log("看看名称", utf8Match, filename) 
    }
    const blob = new Blob([res.data], {
        type: res.headers['content-type'] || 'application/octet-stream'
    });
    // 触发下载
    const url = window.URL.createObjectURL(new Blob([blob]));
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    link.click();
    URL.revokeObjectURL(url);
  } catch (error) {
    console.log('报告生成失败:', error);
  }
}
