async function simulationSubmit(apis, dataCenter, actionCenter, globalUtils, params) {
  console.log("simulationSubmit", params)
  const { isEmpty, openConfirmBox } = globalUtils
  let submitData = []
  params.forEach(item =>{
      let submitItem = {}
      submitItem["task_name"] = item.name
      submitItem["uuid"] = item.uuid
      submitItem["proj_path"] = item.projPath
      submitItem["vehicle_type"] = item.vehicleTypeValue
      submitItem["power_train"] = item.powerTypeValue
      submitItem["cases"] = item.computingTaskValue.map(item => item.name)
      submitItem["partsparameters"] = item.showPartsParams.map(item =>{
        return item.params
      })
      if(!isEmpty(item.dragCoefficient) && false){
          let dragCoefficientParam = []
          let otherParam = {
             "parame_type": "parameter",
          }
          for (const key in item.dragCoefficient) {
              if (item.dragCoefficient.hasOwnProperty(key) && !["id", "name", "choose"].includes(key)) {
                 dragCoefficientParam.push(
                   {
                     "name": key,
                     "value": item.dragCoefficient[key],
                     ...otherParam
                   }
                 )
              }
          }
          submitItem["partsparameters"].push(dragCoefficientParam)
      }
      submitItem["partsparameters"] = submitItem["partsparameters"].flat()
      submitData.push(submitItem)
  })
  const parData = {
    "taskList": submitData
  }
  console.log("submitData", submitData, parData)
  const res = await apis.simulationSubmit(parData)
  console.log("simulationSubmit", "res", res )
  if(res.code !== 200) return
  try {
    const result = await openConfirmBox({
      title: '提示',
      message: '提交成功',
      sureText: '确定',
      cancelText: '关闭'
    });
    console.log('用户确认了操作:', result);
  } catch (error) {
    console.log('用户取消了操作:', error);
  } finally{
    console.log('用户确认or取消了操作:');
  }
}
