// 为数据表select下拉框添加选项
async function getSelectOption (apis, columns, SelectTabKey, pubFun) {
  console.log("getSelectOption", SelectTabKey, columns)
  if(!["component_param","compute_task", "user"].includes(SelectTabKey)) return columns
  if(SelectTabKey === "component_param"){
    let res = await apis.getPartsList()
    if(res.code !== 200) return columns
     const option = pubFun.transformOption(res.data, "componentName", "id")
     return pubFun.addPropertyToObject(columns,"component", "options", option)
  }
  if(SelectTabKey === "compute_task"){
    let res = await apis.getVehicleModel()
    if(res.code !== 200) return columns
    const option = pubFun.transformOption(res.data, "ptName", "id")
    return pubFun.addPropertyToObject(columns,"vehicle","options", option)
  }
  if(SelectTabKey === "user"){
