      {
        label: "高级账号",
        value: "advanced_account"
      },
      {
        label: "普通账号",
        value: "normal_account"
      },
    ]
    return pubFun.addPropertyToObject(columns,"remark","options", option)
  }

}

actionCenter.watchCarDefintion:
({dataCenter, actionCenter, globalUtils}, eventParams) => {
  const { isEmpty, deepCopy } = globalUtils
  const property = eventParams.property[0]
  const newdata = eventParams.value
  const curVehicleTaskObj = dataCenter.curVehicleTaskObj
  console.log("车辆定义值改变", "property", property, "newdata", newdata)
  const updataFun = ()=>{
    let updata = deepCopy({[property]: newdata})
    // 更新当前值
    actionCenter.updataCurVehicleTaskObj({
      data: updata
    })
    // 更新当前编辑的波形列表
    actionCenter.updataVehicleTaskList({uuidStr: curVehicleTaskObj.uuid, data: updata})
  }
  const pubFun = actionCenter.usePublicMethod()
  switch (property) {
      case 'vehicleTypeValue':
        const Option = dataCenter.vehicleTypeOptions.find(item => item.value === newdata);
        const powerTypeOptions = pubFun.getArrayPropertyVal(dataCenter.VehicleDefineJson[Option?.index]?.power, "name", ["components", "computingTask"])
        dataCenter.powerTypeOptions = powerTypeOptions
        updataFun()
        if(isEmpty(powerTypeOptions.find(item => item.value === curVehicleTaskObj.powerTypeValue))){
          actionCenter.updataCurVehicleTaskObj({
            data: {
              "powerTypeValue": "",
              "partsValue": []
            }
          })
        }
        break;
      case 'addVehicleTypeValue':
        const addOption = dataCenter.vehicleTypeOptions.find(item => item.value === newdata);
        const addPowerTypeOptions = pubFun.getArrayPropertyVal(dataCenter.VehicleDefineJson[addOption?.index]?.power, "name", ["components", "computingTask"])
        dataCenter.powerTypeOptions = addPowerTypeOptions
        break;
      case 'VehicleDefineJson':
        dataCenter.vehicleTypeOptions = deepCopy(pubFun.getArrayPropertyVal(newdata, "vehicleType"))
        break;
      case 'powerTypeValue':
        const powerOption = dataCenter.powerTypeOptions.find(item => item.value === newdata);
        updataFun()
        if(isEmpty(powerOption)){
          dataCenter.partsOptions = []
          dataCenter.partsValue = []
          dataCenter.partsParams = []
          dataCenter.computingTask = []
          dataCenter.computingTaskOptions = []
          return
        }
        const otherFields = {
          "visible": true,
    			"closable": false,
    			"disabled": false
        }
        const partsParams = pubFun.addFieldsToItem(powerOption.components, otherFields)
        const computingTask = pubFun.addFieldsToItem(powerOption.computingTask, otherFields)
        dataCenter.partsOptions = powerOption.components
        const partsValue = powerOption.components?.map(item => item.value)
        actionCenter.updataCurVehicleTaskObj({data: { partsValue }})
        dataCenter.partsParams = partsParams
        dataCenter.computingTask = computingTask
        dataCenter.computingTaskOptions = pubFun.transformData(computingTask.filter((i) => i.name === "ErTabs1")[0]?.params)
        break;
      case 'partsValue':
         let showPartsParams = deepCopy(pubFun.filterObjectsByValues(newdata, dataCenter.partsParams, "label"))
         console.log("partsValue———showPartsParams", showPartsParams, "dataCenter.partsParams",  dataCenter.partsParams, "newdata", newdata  )
         if(isEmpty(showPartsParams)){
           actionCenter.updataCurVehicleTaskObj({
               data: {showPartsParams: []}
           })
           return
         }
         if(showPartsParams[0].name !== "ErTabs1"){
           showPartsParams[0].name = "ErTabs1"
           if(showPartsParams[0].label !== dataCenter.curPartsLable){
              dataCenter.partsDesignval = ""
           }
         }
         // 发送请求获取型号
         let getParam = {
              type: "partsDialogVisible",
              name: showPartsParams[0].value,
              val: "component_param"
          }
         dataCenter.curPartsLable = getParam.name
         actionCenter.useRequestControlCenter(getParam)
         updataFun()
         actionCenter.updataCurVehicleTaskObj({
           data: {showPartsParams}
         })
        break;
      case 'showPartsParams':
        updataFun()
        break;
      case 'computingTask':
        break;
      case 'computingTaskValue':
        updataFun()
        break;
      default:
  }
}

