// 判断点击父级还是叶子
function ManageCurVal(dataCenter, actionCenter, globalUtils, data, checkout, curAttribute) {
  if(Array.isArray(data)){
    data.forEach((value) => {
     setCurValData(dataCenter, actionCenter, globalUtils, value, checkout, curAttribute)
    });
  }else{
    setCurValData(dataCenter, actionCenter, globalUtils, data, checkout, curAttribute)
  }
}
function setCurValData(dataCenter, actionCenter, globalUtils, dataObj, checkout, curAttribute) {
    const { isEmpty } =  globalUtils
    let lastdata = dataCenter[curAttribute]
    if(isEmpty(lastdata) && checkout){
      dataCenter[curAttribute] = [dataObj]
      return
    }
    if(checkout){
      const hasval = lastdata.find(item => item.label === dataObj.label);
      if(hasval) return
      dataCenter[curAttribute] = [...dataCenter[curAttribute], dataObj]
    }else{
      const newList = lastdata.filter(item => item.label !== dataObj.label);
      if(isEmpty(newList)) {
         dataCenter[curAttribute] = []
         return
      }
      dataCenter[curAttribute] = newList
    }
}

