actionCenter.updataVehicleTaskList:
({dataCenter, actionCenter, globalUtils}, eventParams) => {
  const { isEmpty, createUuid, nameRepeat } =  globalUtils
  const { type, uuidStr, data } = eventParams.params[0] 
  const pubFun = actionCenter.usePublicMethod()
  const operations = {
        clear: () => dataCenter.VehicleTaskList = [],
        add: () => {
          if (isEmpty(data)) return;
          dataCenter.VehicleTaskList = [...dataCenter.VehicleTaskList, data];
          actionCenter.updataCurVehicleTaskObj({data})
        },
        cover: () => {
          if (isEmpty(data)) return;
          dataCenter.VehicleTaskList = data;
        },
        delete: () => {
          if (isEmpty(uuidStr)) return;
          const newList =  dataCenter.VehicleTaskList.filter(item => item.uuid !== uuidStr);
          if(isEmpty(newList)) {
            pubFun.clearAllData()
            return;
          }
          dataCenter.VehicleTaskList = [...newList];
          actionCenter.updataCurVehicleTaskObj({data: newList[newList.length - 1]})
        },
        copy: () => {
          if (isEmpty(uuidStr)) return;
          const uuid = createUuid();
          let name = pubFun.formattedNaming(dataCenter.curVehicleTaskObj.name, 'Copy')
          name = nameRepeat(name, dataCenter.VehicleTaskList);
          dataCenter.VehicleTaskList = [...dataCenter.VehicleTaskList, { ...dataCenter.curVehicleTaskObj, name, uuid }];
          actionCenter.updataCurVehicleTaskObj({data: { name, uuid}})
        },
        default: () => {
          if (isEmpty(uuidStr) && isEmpty(data)) return;
          const newList = dataCenter.VehicleTaskList?.map(item => (item?.uuid === uuidStr ? { ...item, ...data } : item));
          dataCenter.VehicleTaskList = [...newList];
        },
      };
   const operation = operations[type] || operations.default;
   operation();
}

