          break;
        case 'DataOptionsValue':
          let labDataVal = {
             type: "DataOptionsValue",
             name: "表格数据",
             val:  newdata
          }
          if(isEmpty(newdata)){
            win.setWinList({ type: "clear", attribute: "tableWinList", curAttribute: "curTableWin"})
            return
          }
          actionCenter.useRequestControlCenter(labDataVal)
          break;
        case 'currentParameterValue':
          const PLOTLY_DEFAULT_COLORS = [
            '#1f77b4', '#ff7f0e', '#2ca02c', '#d62728',
            '#9467bd', '#8c564b', '#e377c2', '#7f7f7f'
          ];
          // 创建图表布局
          const layout = {
              title: 'Multiple Y Axes Example',
              paper_bgcolor: "#eeeeee",
              plot_bgcolor: "#ffffff",
              xaxis: {
                  title: 'Time',
                  zeroline: false,
                  showline: true,
                  mirror: true,
                  domain: [0, 0.85],
              },
              yaxis: {
                    anchor: "y",
                    title: 'Amplitude',
                    showgrid: false,
                    zeroline: false,
                    showline: true,
                    nticks: 10,
                    mirror: true,
                    titlefont: { color: PLOTLY_DEFAULT_COLORS[0] },
                    tickfont: { color: PLOTLY_DEFAULT_COLORS[0] },
              },
              margin: {
                l: 50,
                r: 20,
                t: 40,
                b: 40
              },
              legend: {
                xanchor: "right",
                x: 0.99,
                y: 0.98,
                bgcolor: "#ffffff",
                bordercolor: "#cccccc",
                borderwidth: 1,
                traceorder: "normal",
                font: {
                    size: 10
                },
                itemwidth: 20,
                itemheight: 20,
              },
          };
          const plotData = newdata.filter(item => isEmpty(item?.children)).map((item1, idx) =>{
            const color = PLOTLY_DEFAULT_COLORS[idx % PLOTLY_DEFAULT_COLORS.length];
            const axisNumber = idx + 1;
            if(axisNumber > 1 ){
              layout[`yaxis${axisNumber}`] = createYAxisLayout(axisNumber, color)
            }
            return createPlotTrace(dataCenter.plotDataX, item1, axisNumber, color)
          })
          console.log("用户勾选当前参数变化", plotData, layout)
          win.setWinList({ 
            uuidStr: dataCenter.curPlotWin.uuid, 
            attribute: "plotWinList", 
            curAttribute:"curPlotWin", 
            data:{ 
              currentParameterValue: newdata.map(item => item.label),
              propValue: {
                ...dataCenter.curPlotWin.propValue,
                dataSource: plotData,
                layout: layout
              }
            }})
          break;
        default:
    }
}

// 创建Y轴配置的工厂函数
function createYAxisLayout(axisNumber, color) {
  return {
    position: 1 - (axisNumber - 2) * 0.01, 
    side: "right",  
    anchor: "free",       
    overlaying: "y",
    showgrid: false,
    showline: true,
    zeroline: false,
    mirror: true,
    titlefont: { 
      color: color,
      size: 10,
      family: 'Arial'
    },
    tickfont: { 
      color: color,
      size: 8
    },
    automargin: true,
    autorange: true,
    separatethousands: true,
    fixedrange: false,
  };
}
// 创建数据轨迹的工厂函数
function createPlotTrace(xData, item, axisNumber, color) {
  return {
    x: xData,
    y: item.y,
    name: item.label,
    type: 'scatter',
    mode: 'lines',
    yaxis: `y${axisNumber}`,
    line: { color }
  };
}

actionCenter.handleOperate:
