  }
}

actionCenter.handValChang:
({dataCenter, actionCenter, globalUtils}, eventParams) => {
  console.log("handValChang表单值改变", eventParams)
  const { isEmpty, deepCopy } = globalUtils
  const moduleName = eventParams.moduleName
  const pubFun = actionCenter.usePublicMethod()
  switch(moduleName){
    case "ErForm":
      const itemVal = eventParams.params.item
      if(itemVal.name !== "valueType" && dataCenter.currentSelectTabKey !== "component" ) return
      if(eventParams.newValue === "table"){
        dataCenter.addDbTableForm = dataCenter.addDbTableForm.map((item)=>{
          if(item.type === "table"){
            return {
              ...item,
              visible: true
            }
          }
          return item
        })
      }else{
        dataCenter.addDbTableForm = dataCenter.addDbTableForm.map((item)=>{
          if(item.type === "table"){
            return {
              ...item,
              visible: false
            }
          }
          return item
        })
      }
      break;
    case "VSelect":
      const property = eventParams.property[0]
      let valParams =  eventParams.params
      if(property === "partsModelVal"){
        let formParams = []
        if(valParams?.params){
          formParams = valParams.params
        }
        console.log("handValChang表单值改变零部件参数", property, valParams, formParams)
        dataCenter.partsAddDbTableForm = formParams
        return
      }
      if(dataCenter.DragCalculationDialogVisible){
        let formParams = []
        if(valParams?.params){
          formParams = pubFun.transformAtoB(valParams.params, { lab: "name", val: "value"})
        }
        console.log("handValChang表单值改变助力系数", property, valParams, formParams)
        dataCenter.refForm = formParams
        return
      }
      if(true){
        console.log("handValChang表单值改变车辆定义", valParams, "dataCenter.showPartsParams",  dataCenter.showPartsParams,"dataCenter.curPartsLable", dataCenter.curPartsLable)
        let oldParams = dataCenter.showPartsParams.find(item => item.value === dataCenter.curPartsLable)
        let newParams = valParams.params
        oldParams.params = newParams
        dataCenter.partsEditForm = newParams
        if(dataCenter.curPartsLable === "Vehicle"){
          dataCenter.scaleForm = deepCopy(newParams)
        }
        return
      }
      break;
    default:
  }
}

